CREATE DATABASE IF NOT EXISTS skillswap CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE skillswap;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,university VARCHAR(150),department VARCHAR(150),role ENUM('student','admin') NOT NULL DEFAULT 'student');
CREATE TABLE user_phones(phone_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,phone VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE skills(skill_id INT AUTO_INCREMENT PRIMARY KEY,skill_name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE user_skills(user_id INT NOT NULL,skill_id INT NOT NULL,skill_type ENUM('offered','wanted') NOT NULL,proficiency ENUM('Beginner','Intermediate','Advanced') NOT NULL DEFAULT 'Beginner',PRIMARY KEY(user_id,skill_id,skill_type),FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(skill_id) ON DELETE CASCADE);
CREATE TABLE availability(avail_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,day_of_week ENUM('Mon','Tue','Wed','Thu','Fri','Sat','Sun') NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE requests(request_id INT AUTO_INCREMENT PRIMARY KEY,sender_id INT NOT NULL,receiver_id INT NOT NULL,skill_id INT NOT NULL,status ENUM('pending','accepted','rejected') NOT NULL DEFAULT 'pending',requested_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sender_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(receiver_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(skill_id) ON DELETE CASCADE);
CREATE TABLE sessions(session_id INT AUTO_INCREMENT PRIMARY KEY,request_id INT NOT NULL,session_date DATE NOT NULL,session_time TIME NOT NULL,mode ENUM('Online','In-person') NOT NULL,FOREIGN KEY(request_id) REFERENCES requests(request_id) ON DELETE CASCADE);
CREATE TABLE reviews(review_id INT AUTO_INCREMENT PRIMARY KEY,session_id INT NOT NULL,reviewer_id INT NOT NULL,rating TINYINT NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT,review_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(session_id,reviewer_id),FOREIGN KEY(session_id) REFERENCES sessions(session_id) ON DELETE CASCADE,FOREIGN KEY(reviewer_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE notifications(notification_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,message VARCHAR(500) NOT NULL,type VARCHAR(30) NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,sent_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE);
-- average rating RECEIVED by each user (reviews written by their session partner)
CREATE VIEW user_ratings AS SELECT u.user_id,ROUND(AVG(v.rating),2) avg_rating,COUNT(v.review_id) review_count FROM users u JOIN requests r ON (r.sender_id=u.user_id OR r.receiver_id=u.user_id) JOIN sessions s ON s.request_id=r.request_id JOIN reviews v ON v.session_id=s.session_id AND v.reviewer_id<>u.user_id GROUP BY u.user_id;
